"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowUpRight } from "lucide-react";

const experiences = [
  {
    period: "2023 - Present",
    title: "Python Django Full-Stack Developer",
    company: "Mystro Training",
    description:
      "Build and maintain full-stack applications using Django framework. Work closely with modern technologies including Docker, Celery, Redis, and Vue.js to implement and advocate for best practices in web development.",
    highlights: [
      "Created responsive websites with HTML, CSS, Bootstrap and JavaScript",
      "Built automation scripts with Python for workflow optimization",
      "Developed RESTful APIs with Django REST Framework",
      "Integrated payment systems including Stripe",
      "Deployed applications to cloud using Render",
    ],
    tech: ["Python", "Django", "DRF", "Docker", "Vue.js", "Redis", "Celery"],
  },
];

const education = {
  period: "2023 - 2024",
  degree: "Full-Stack Python & Web Development",
  school: "Mystro E-Learning School",
  type: "Bootcamp",
};

export function ExperienceSection() {
  const [isVisible, setIsVisible] = useState(false);
  const [isClient, setIsClient] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    setIsClient(true);
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section
      ref={sectionRef}
      id="experience"
      className="relative py-32 px-6 lg:px-12"
    >
        {/* Clean subtle background */}
        <div className="absolute inset-0 overflow-hidden">
          {/* Simple gradient overlay */}
          <div 
            className="absolute inset-0 opacity-15"
            style={{
              background: `radial-gradient(ellipse at center, 
                rgba(94, 234, 212, 0.12) 0%, 
                transparent 70%)`,
            }}
          />
          
          {/* Minimal particles */}
          {isClient && (
            <div className="absolute inset-0">
              {[...Array(12)].map((_, i) => (
                <div
                  key={i}
                  className="absolute w-1 h-1 rounded-full"
                  style={{
                    background: `rgba(94, 234, 212, 0.4)`,
                    top: `${Math.random() * 100}%`,
                    left: `${Math.random() * 100}%`,
                    animation: `gentle-pulse ${3 + Math.random() * 2}s ease-in-out infinite`,
                    animationDelay: `${Math.random() * 3}s`,
                  }}
                />
              ))}
            </div>
          )}
        </div>

      <div className="relative max-w-6xl mx-auto z-10">
        {/* Section header */}
        <div
          className={`flex items-center gap-4 mb-16 transition-all duration-700 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <span className="font-mono text-primary text-sm">02.</span>
          <h2 className="text-2xl sm:text-3xl font-bold text-foreground">Languages</h2>
          <div className="flex-1 h-px bg-border max-w-[300px]" />
        </div>

        {/* Languages */}
        <div
          className={`transition-all duration-700 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <div className="flex flex-wrap gap-4">
            {["Arabic (Native)", "English (Fluent)", "German (Conversational)"].map((lang) => (
              <div
                key={lang}
                className="px-4 py-2 bg-card/50 rounded-lg border border-border text-sm text-foreground hover:border-primary/40 transition-colors"
              >
                {lang}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
